const LABELS = {
 'Undergraduate':'Licenciatura / graduação','Postgraduate':'Pós-graduação / mestrado','Diploma':'Diploma','Certificate':'Certificado','Dual degree':'Dupla titulação','Professional degree':'Formação profissional superior','Other pathways':'Outras formações','Doctoral':'Doutoramento',
 'Management Studies':'Gestão','Ayurved':'Medicina ayurvédica','Engineering & Technology':'Engenharia e tecnologia','IT & Computer Science':'Informática e ciências da computação','Interdisciplinary / confirm faculty':'Interdisciplinar / área por confirmar','Performing Arts':'Artes performativas','Hotel Management & Catering':'Hotelaria e restauração','Architecture & Planning':'Arquitectura e planeamento','Design':'Design','Nursing':'Enfermagem','Pharmacy':'Farmácia','Commerce':'Comércio','Law':'Direito','Fine Arts':'Belas-artes','Social Work':'Serviço social','Library & Information Science':'Biblioteconomia e ciência da informação','Applied Sciences':'Ciências aplicadas','Agriculture':'Agricultura','Homeopathy':'Homeopatia','Physiotherapy':'Fisioterapia','Liberal Arts':'Artes e humanidades',
 "Bachelor's Programs (Regular & Hons)":'Licenciaturas (regular e honours)','Bachelors Programs':'Licenciaturas','Masters programs':'Mestrados','Diploma Programs':'Cursos de diploma','Certificate Programs':'Cursos de certificado','Dual Degree':'Dupla titulação','WIP Programs':'Estudo integrado com trabalho','Health Sector Skill Programs':'Formação técnica em saúde','Industry Embedded':'Formação integrada com a indústria','Pathway Program':'Percurso académico internacional','Global Programs':'Programas globais','Doctoral & Post-doctoral Program':'Doutoramento e pós-doutoramento'
};
const labelPT = value => LABELS[value] || value;
const durationPT = value => value ? value.replace(/years?/gi,'anos').replace(/months?/gi,'meses').replace(/semesters?/gi,'semestres').replace(/weeks?/gi,'semanas').replace(/days?/gi,'dias').replace(/hours?/gi,'horas').replace(/programs?/gi,'de formação').replace(/\b1 anos\b/g,'1 ano').replace(/\b1 meses\b/g,'1 mês').replace(/\b1 semanas\b/g,'1 semana').replace(/\b1 dias\b/g,'1 dia').replace(/\b1 horas\b/g,'1 hora') : 'Confirme com a universidade';
const normalize = value => String(value).toLocaleLowerCase('pt').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const SEARCH_TERMS = {informatica:'computer',computacao:'computer',engenharia:'engineering',enfermagem:'nursing',gestao:'management',contabilidade:'accounting',medicina:'medicine',psicologia:'psychology',direito:'law',turismo:'tourism',farmacia:'pharmacy',ciencias:'science',ciencia:'science',agricultura:'agriculture',arquitectura:'architecture',educacao:'education',mestrado:'master',licenciatura:'bachelor',diploma:'diploma',certificado:'certificate',artes:'arts',tecnologia:'technology'};
const $ = id => document.getElementById(id);
const money = value => new Intl.NumberFormat('pt-MZ',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(value);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chatURL = (message,advisor='india') => 'https://wa.me/'+CONFIG.whatsapp[advisor]+'?text='+encodeURIComponent(message);
// There is deliberately no fetch: the catalogue works when index.html is opened directly.
let page=1;
const pageSize=9;
const sortedCourses=COURSES.map((c,id)=>({...c,id})).sort((a,b)=>a.name.localeCompare(b.name));
function option(value,label=value){const o=document.createElement('option');o.value=value;o.textContent=label;return o;}
for(const faculty of [...new Set(COURSES.map(c=>c.faculty))].sort()) $('faculty').append(option(faculty,labelPT(faculty)));
for(const level of [...new Set(COURSES.map(c=>c.level))].sort()) $('level').append(option(level,labelPT(level)));
for(const c of sortedCourses){$('calc-course').append(option(c.id,c.name));$('course-options').append(option(c.name));}
function filteredCourses(){
 const q=normalize($('search').value.trim()), faculty=$('faculty').value, level=$('level').value;
 const words=q.split(/\s+/).filter(w=>w&&!['de','da','do','das','dos','e','em'].includes(w));
 const result=sortedCourses.filter(c=>{const haystack=normalize(c.name+' '+c.faculty+' '+c.track+' '+labelPT(c.faculty)+' '+labelPT(c.level));return words.every(w=>haystack.includes(w)||haystack.includes(SEARCH_TERMS[w]||w))&&(!faculty||c.faculty===faculty)&&(!level||c.level===level);});
 if($('sort').value!=='name') result.sort((a,b)=>{
  const av=Number.isFinite(a.annualFee),bv=Number.isFinite(b.annualFee);
  if(av!==bv)return av?-1:1;
  if(av&&a.annualFee!==b.annualFee)return $('sort').value==='feeAsc'?a.annualFee-b.annualFee:b.annualFee-a.annualFee;
  return a.name.localeCompare(b.name);
 });
 return result;
}
function renderCourses(){
 const result=filteredCourses(),pages=Math.max(1,Math.ceil(result.length/pageSize));page=Math.min(page,pages);
 $('result-count').textContent=result.length+' de '+COURSES.length+' cursos listados · consulta em 25 Out 2026';
 $('sort-note').hidden=$('sort').value==='name'||result.some(c=>Number.isFinite(c.annualFee));
 $('course-list').innerHTML=result.length?result.slice((page-1)*pageSize,page*pageSize).map((c,i)=>`<article class="course-card"><div class="course-top"><span class="tag">${escapeHTML(labelPT(c.level))}</span><span class="course-num">${String((page-1)*pageSize+i+1).padStart(2,'0')}</span></div><h3>${escapeHTML(c.name)}</h3><p class="faculty-line">${escapeHTML(labelPT(c.faculty))}</p><p class="fee-line">${c.annualFee===null?'Contacte-nos para confirmar a propina internacional':money(c.annualFee)+' / ano'}</p><details><summary>Detalhes do curso</summary><p><strong>Qualificação:</strong> ${escapeHTML(c.name)}<br><strong>Duração:</strong> ${escapeHTML(durationPT(c.duration))}<br><strong>Regime de estudo:</strong> ${escapeHTML(labelPT(c.track))}</p><p>Confirme os requisitos de entrada, as equivalências, as taxas obrigatórias e as vagas para o seu caso. O total de propinas não está confirmado.</p><p><a href="${escapeHTML(c.source)}" target="_blank" rel="noopener">Informação oficial do curso ↗</a></p><p class="source-note">Fonte consultada em 25 de Outubro de 2026.</p></details><button class="apply-course" data-course="${c.id}">Candidatar-me com a ADA <span>↗</span></button></article>`).join(''):'<div class="empty"><h3>Nenhum curso encontrado</h3><p>Experimente outra palavra ou limpe os filtros.</p></div>';
 $('page-status').textContent=result.length?'Página '+page+' de '+pages:'Sem resultados';$('prev').disabled=page<=1;$('next').disabled=page>=pages;
}
for(const id of ['search','faculty','level','sort']) $(id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderCourses();});
$('reset').addEventListener('click',()=>{for(const id of ['search','faculty','level'])$(id).value='';$('sort').value='name';page=1;renderCourses();});
for(const [id,delta] of [['prev',-1],['next',1]])$(id).addEventListener('click',()=>{page+=delta;renderCourses();$('result-count').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
$('course-list').addEventListener('click',e=>{const b=e.target.closest('[data-course]');if(!b)return;const c=COURSES[Number(b.dataset.course)];$('enquiry-course').value=c.name;$('calc-course').value=b.dataset.course;document.querySelector('#contact').scrollIntoView();$('enquiry-course').focus({preventScroll:true});});
$('menu').addEventListener('click',()=>{const open=$('menu').getAttribute('aria-expanded')!=='true';$('menu').setAttribute('aria-expanded',String(open));$('navigation').classList.toggle('open',open);});
$('navigation').addEventListener('click',e=>{if(e.target.closest('a')){$('menu').setAttribute('aria-expanded','false');$('navigation').classList.remove('open');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('menu').setAttribute('aria-expanded','false');$('navigation').classList.remove('open');}});
// Quote worksheet: each year has its own fields; blank values never mean a confirmed zero.
let yearInputs={};
function saveYears(){document.querySelectorAll('#year-fields input').forEach(el=>yearInputs[el.id]=el.value);}
function renderYears(){saveYears();const years=Number($('years').value),hostel=$('hostel').value!=='none';$('year-fields').innerHTML=Array.from({length:years},(_,i)=>`<div class="year-row"><p>ANO ${i+1} · valor anual da cotação</p><div class="two-col"><label>Propinas (INR)<input type="number" id="tuition-${i}" min="0" max="1000000000" step="0.01" placeholder="Valor da cotação, ou 0 se confirmado" value="${escapeHTML(yearInputs['tuition-'+i]||'')}"></label>${hostel?`<label>Alojamento e refeições (INR)<input type="number" id="hostel-${i}" min="0" max="1000000000" step="0.01" placeholder="Confirme os serviços incluídos" value="${escapeHTML(yearInputs['hostel-'+i]||'')}"></label>`:''}</div></div>`).join('');calculate();}
function calculate(){
 let tuition=0,accommodation=0,missing=0,invalid=false;const years=Number($('years').value),hostel=$('hostel').value!=='none';
 function read(id){const el=$(id),n=el.valueAsNumber;if(el.value===''){missing++;return 0;}if(!Number.isFinite(n)||n<0||!el.validity.valid){invalid=true;return 0;}return n;}
 for(let i=0;i<years;i++){tuition+=read('tuition-'+i);if(hostel)accommodation+=read('hostel-'+i);}
 let other=read('other-fees');
 $('cost-result').innerHTML=invalid?'<p>Introduza valores válidos, iguais ou superiores a zero. Ainda não é possível calcular o total.</p>':`<p>${missing?'PLANO PARCIAL · '+missing+' valor(es) por preencher':'TOTAL DO PLANO · COM BASE NA COTAÇÃO INTRODUZIDA'}</p><dl><div><dt>Propinas · ${years} ano(s)</dt><dd>${money(tuition)}</dd></div><div><dt>${hostel?'Alojamento e refeições':'Residência universitária · não seleccionada'}</dt><dd>${hostel?money(accommodation):'Excluído'}</dd></div><div><dt>Outros encargos da universidade</dt><dd>${money(other)}</dd></div><div class="total"><dt>${missing?'Subtotal introduzido':'Custos universitários previstos'}</dt><dd>${money(tuition+accommodation+other)}</dd></div></dl><p>${missing?'Os campos vazios representam custos por confirmar. O subtotal não é uma estimativa completa.':'Este cálculo não verifica os preços introduzidos.'}</p>`;
}
$('years').addEventListener('change',renderYears);$('hostel').addEventListener('change',renderYears);$('year-fields').addEventListener('input',calculate);$('other-fees').addEventListener('input',calculate);
$('calc-course').addEventListener('change',()=>{yearInputs={};$('year-fields').innerHTML='';const c=COURSES[Number($('calc-course').value)];if($('calc-course').value!==''&&c){$('enquiry-course').value=c.name;const m=(c.duration||'').match(/^(\d+)\s*years?$/i);$('years').value=m&&Number(m[1])<=8?m[1]:'1';}renderYears();});
$('quote-enquiry').addEventListener('click',()=>{if($('calc-course').value!=='')$('enquiry-course').value=COURSES[Number($('calc-course').value)].name;document.querySelector('[name="questions"]').value='Gostaria de receber uma cotação internacional actualizada, por escrito, com propinas, alojamento, encargos obrigatórios e períodos de pagamento.';});
$('enquiry').addEventListener('submit',e=>{
 e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;
 const data=new FormData(form);if(!String(data.get('name')).trim()||!String(data.get('course')).trim()||!String(data.get('country')).trim()||!String(data.get('intake')).trim()){ $('form-result').hidden=false;$('form-result').textContent='Preencha os campos obrigatórios com os seus dados.';return;}
 const message=['Olá ADA Education,','Gostaria de solicitar: '+data.get('request')+'.','','Nome: '+data.get('name'),'País: '+data.get('country'),'Email: '+data.get('email'),'WhatsApp: '+data.get('phone'),'Curso pretendido: '+data.get('course'),'Formação concluída: '+data.get('education'),'Ano / época de ingresso: '+data.get('intake'),'Perguntas: '+(String(data.get('questions')).trim()||'Gostaria de orientação sobre os próximos passos.')].join('\n');
 const url=chatURL(message,data.get('advisor'));$('form-result').hidden=false;$('form-result').replaceChildren();const p=document.createElement('p');p.textContent='O seu pedido está pronto. Reveja a mensagem no WhatsApp e carregue em Enviar quando estiver pronto.';const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent='Abrir a mensagem preparada no WhatsApp ↗';$('form-result').append(p,a);window.open(url,'_blank','noopener');
});
const hero=$('hero-image');hero.addEventListener('error',()=>{hero.hidden=true;document.querySelector('.photo-credit').textContent='Conheça o campus na galeria oficial da Parul University.';});hero.src=CONFIG.campusImage;
$('copyright-year').textContent=new Date().getFullYear();renderCourses();renderYears();
